test('an upload for an Album, an Artist or a MediaTrack is staged privately without changing the catalog', async () => {
    const revisions = await Promise.all((['album', 'artist', 'audioTrack'] as const).map(revision)), coverArt = (await db().collection('artists').findOne({ _id: artist }))!.coverArtId;
    const formats = [['image/png', await png(6, 4), '封面 "review".png'], ['image/jpeg', await sharp({ create: { width: 6, height: 4, channels: 3, background: '#38c' } }).jpeg().toBuffer(), 'cover.jpg'],
        ['image/webp', await sharp({ create: { width: 6, height: 4, channels: 3, background: '#c83' } }).webp().toBuffer(), 'cover.webp']] as const;
    for (const kind of ['album', 'artist', 'audioTrack'] as const) for (const [type, bytes, filename] of formats) {
        const key = randomUUID(), response = await send(kind, hex(owners[kind]), fileBody(bytes, type, filename), key);
        assert.equal(response.status, 200, `${kind} ${type}`); const body = await response.json();
        assert.deepEqual(Object.keys(body).sort(), ['receipt', 'upload']); assert.match(body.upload.id, /^[0-9a-f]{24}$/); assert.deepEqual(body.receipt, { operationId: key });
        const saved = await record(body.upload.id), put = storage.puts.at(-1)!, sha256 = createHash('sha256').update(put.bytes).digest('hex');
        assert.deepEqual({ kind: saved.kind, ownerId: saved.ownerId, actorId: saved.actorId, operationId: saved.operationId, usedBy: saved.usedBy },
            { kind, ownerId: hex(owners[kind]), actorId: hex(actor), operationId: key, usedBy: null });
        assert.deepEqual({ bucket: saved.asset.bucket, key: saved.asset.key, sha256: saved.asset.sha256, byteLength: saved.asset.byteLength, contentType: saved.asset.contentType, filename: saved.asset.filename, state: saved.asset.state },
            { bucket: 'private-imports', key: `imports/catalog-covers/${body.upload.id}`, sha256, byteLength: put.bytes.length, contentType: type, filename, state: 'ready' });
        assert.deepEqual(put.target, { bucket: 'private-imports', key: `imports/catalog-covers/${body.upload.id}`, sha256, byteLength: put.bytes.length, contentType: type, importId: body.upload.id, slotId: 'cover', operationId: key });
        assert.ok(saved.asset.etag && saved.asset.versionId);
    }
    assert.equal(storage.puts.length, 9);
    assert.deepEqual(await Promise.all((['album', 'artist', 'audioTrack'] as const).map(revision)), revisions);
    assert.equal((await db().collection('artists').findOne({ _id: artist }))!.coverArtId, coverArt);
    assert.equal(await db().collection('imageAssets').countDocuments(), 1); assert.equal(await operations().countDocuments(), 0);
});

test('the staged bytes are normalized: orientation applied and every kind of embedded metadata removed', async () => {
    const exif = { IFD0: { Make: 'SyntheticMake', Model: 'SyntheticModel' }, IFD2: { BodySerialNumber: 'SYN-SERIAL-0001' }, IFD3: { GPSLatitudeRef: 'N', GPSLatitude: '12/1 34/1 56/1', GPSLongitudeRef: 'E', GPSLongitude: '65/1 43/1 21/1' } };
    const jpeg = await twoColour(40, 20).jpeg({ quality: 95 }).withExif(exif).withMetadata({ orientation: 6 }).toBuffer();
    const plain = await twoColour(40, 20).png().toBuffer();
    const taggedPng = beforeImageData(plain, chunk('eXIf', orientationExif(6)), chunk('tEXt', Buffer.from('Comment\0SyntheticMake SYN-SERIAL-0001', 'latin1')));
    const xmp = '<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"/></x:xmpmeta>';
    const webp = await twoColour(40, 20).webp({ quality: 95 }).withExif({ IFD0: { Make: 'SyntheticMake' }, IFD2: { BodySerialNumber: 'SYN-SERIAL-0001' } }).withXmp(xmp).withMetadata({ orientation: 8 }).toBuffer();
    assert.equal((await sharp(taggedPng).metadata()).orientation, 6); assert.ok((await sharp(webp).metadata()).xmp);
    for (const [type, input, redOnTop] of [['image/jpeg', jpeg, true], ['image/png', taggedPng, true], ['image/webp', webp, false]] as const) {
        assert.equal((await send('album', hex(album), fileBody(input, type, 'tagged'))).status, 200, type);
        const body = storage.puts.at(-1)!.bytes, meta = await sharp(body).metadata();
        assert.equal(meta.format, type.slice(6)); assert.equal(meta.width, 20); assert.equal(meta.height, 40);
        for (const key of ['exif', 'xmp', 'iptc', 'icc', 'comments', 'orientation'] as const) assert.equal(meta[key], undefined, `${type} ${key}`);
        for (const marker of ['Exif', 'eXIf', 'tEXt', 'iTXt', 'XMP ', 'x:xmpmeta', 'SyntheticMake', 'SYN-SERIAL-0001']) assert.equal(body.includes(marker), false, `${type} ${marker}`);
        const { data, info } = await sharp(body).removeAlpha().raw().toBuffer({ resolveWithObject: true }), pixel = (x: number, y: number) => data.subarray((y * info.width + x) * 3, (y * info.width + x) * 3 + 3);
        const [top, bottom] = [pixel(10, 5), pixel(10, 35)], red = (value: Buffer) => value[0] > 180 && value[2] < 80, blue = (value: Buffer) => value[2] > 180 && value[0] < 80;
        assert.ok(redOnTop ? red(top) && blue(bottom) : blue(top) && red(bottom), `${type} orientation`);
        assert.deepEqual(await normalizeCoverUpload(input, type), body);
    }
    // PNG stays lossless: the decoded pixels are the oriented input's.
    assert.deepEqual(await sharp(storage.puts[1].bytes).removeAlpha().raw().toBuffer(), await sharp(taggedPng).rotate().removeAlpha().raw().toBuffer());
});

test('refused uploads store no record and send nothing to storage, and an image refusal comes before a filename refusal', async () => {
    const path = `/catalog/album/${hex(album)}/cover-uploads`, valid = await png();
    const declared = await new Promise<number>((resolve, reject) => {
        const request = httpRequest(`${base}/api/admin/v1${path}`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': String(12 * 1024 * 1024), 'Idempotency-Key': randomUUID() } },
            response => { resolve(response.statusCode!); response.resume(); request.destroy(); });
        request.on('error', error => { if (!(error as NodeJS.ErrnoException).code?.startsWith('ECONNRESET')) reject(error); }); request.flushHeaders();
    });
    assert.equal(declared, 413);
    const oversized = Buffer.concat([valid.subarray(0, 8), Buffer.alloc(maxCoverArtInputBytes + 1 - 8)]);
    await expectCode(await send('album', hex(album), fileBody(oversized, 'image/png')), 413, 'ADMIN_CATALOG_COVER_TOO_LARGE');
    const gif = Buffer.from('R0lGODlhAQABAIAAAP///wAAACH5BAEAAAAALAAAAAABAAEAAAICRAEAOw==', 'base64'), jpeg = await sharp({ create: { width: 64, height: 64, channels: 3, background: '#555' } }).jpeg().toBuffer();
    const red = await png(8, 8, '#f00'), blue = await png(8, 8, '#00f'), animated = await sharp([red, blue], { join: { animated: true } }).webp().toBuffer();
    for (const [bytes, type] of [[gif, 'image/gif'], [valid, 'image/jpeg'], [jpeg.subarray(0, jpeg.length - 40), 'image/jpeg'], [await png(4001, 4001), 'image/png'],
        [animated, 'image/webp'], [await apng(), 'image/png'], [Buffer.alloc(0), 'image/png']] as const)
        await expectCode(await send('album', hex(album), fileBody(bytes, type)), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    // The image is checked before its name, so a refused image under a refused name answers the image refusal.
    await expectCode(await send('album', hex(album), fileBody(jpeg.subarray(0, jpeg.length - 40), 'image/jpeg', 'bad\u0001name.jpg')), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    for (const body of [multipart({ bytes: valid, type: 'image/png', filename: 'a.png' }, { bytes: valid, type: 'image/png', filename: 'b.png' }), multipart({ bytes: Buffer.from('note'), name: 'note' }, { bytes: valid, type: 'image/png', filename: 'a.png' }),
        Buffer.from(`--${boundary}--\r\n`), fileBody(valid, 'image/png', 'bad\u0001name.png'), fileBody(valid, 'image/png', `${'n'.repeat(252)}.png`)])
        await expectCode(await send('album', hex(album), body), 400, 'ADMIN_CATALOG_INVALID_INPUT');
    for (const key of [null, 'not-a-key']) await expectCode(await send('album', hex(album), fileBody(valid, 'image/png'), key), 400, 'ADMIN_CATALOG_INVALID_INPUT');
    await expectCode(await send('organization', hex(new ObjectId()), fileBody(valid, 'image/png')), 400, 'ADMIN_CATALOG_COVER_UNSUPPORTED');
    await expectCode(await send('playlist', hex(album), fileBody(valid, 'image/png')), 400, 'ADMIN_CATALOG_INVALID_INPUT');
    await expectCode(await send('album', hex(new ObjectId()), fileBody(valid, 'image/png')), 404, 'ADMIN_CATALOG_NOT_FOUND');
    await db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'pending' } });
    await expectCode(await send('album', hex(album), fileBody(valid, 'image/png')), 404, 'ADMIN_CATALOG_NOT_FOUND');
    assert.equal((await send('artist', hex(artist), fileBody(valid, 'image/png'), randomUUID(), userToken)).status, 403);
    process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'false';
    await expectCode(await send('artist', hex(artist), fileBody(valid, 'image/png')), 503, 'ADMIN_IMPORT_STORAGE_UNAVAILABLE');
    process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'true'; process.env.ADMIN_IMPORT_S3_BUCKET_NAME = 'catalog';
    await expectCode(await send('artist', hex(artist), fileBody(valid, 'image/png')), 503, 'ADMIN_IMPORT_STORAGE_UNAVAILABLE');
    assert.equal(await records().countDocuments(), 0); assert.equal(storage.puts.length, 0);
});

/** Sends an upload's headers and the optional start of its body, then reads the status and code the route answers before the body ends. */
const early = (path: string, headers: Record<string, string>, auth: string | null = token) => new Promise<{ status: number; code?: string }>((resolve, reject) => {
    const request = httpRequest(`${base}/api/admin/v1${path}`, { method: 'POST', headers: { ...(auth ? { Authorization: `Bearer ${auth}` } : {}), 'Content-Type': `multipart/form-data; boundary=${boundary}`, ...headers } }, response => {
        const chunks: Buffer[] = []; response.on('data', part => chunks.push(part));
        response.on('end', () => { request.destroy(); const text = Buffer.concat(chunks).toString(); resolve({ status: response.statusCode!, code: text ? JSON.parse(text).code : undefined }); });
    });
    request.on('error', error => { if (!(error as NodeJS.ErrnoException).code?.startsWith('ECONNRESET')) reject(error); }); request.flushHeaders();
});

test('the route checks the item kind, intent key and storage before upload capacity or the body, and needs a declared length and a signed-in administrator', async () => {
    const path = `/catalog/album/${hex(album)}/cover-uploads`, large = { 'Content-Length': String(12 * 1024 * 1024) };
    assert.deepEqual(await early(path, { ...large, 'Idempotency-Key': 'not-a-key' }), { status: 400, code: 'ADMIN_CATALOG_INVALID_INPUT' });
    assert.deepEqual(await early(`/catalog/organization/${hex(new ObjectId())}/cover-uploads`, { ...large, 'Idempotency-Key': randomUUID() }), { status: 400, code: 'ADMIN_CATALOG_COVER_UNSUPPORTED' });
    process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'false';
    assert.deepEqual(await early(path, { ...large, 'Idempotency-Key': randomUUID() }), { status: 503, code: 'ADMIN_IMPORT_STORAGE_UNAVAILABLE' });
    process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'true';
    // A chunked body declares no length, so the size guard answers before anything is parsed.
    assert.deepEqual(await early(path, { 'Transfer-Encoding': 'chunked', 'Idempotency-Key': randomUUID() }), { status: 411, code: undefined });
    assert.equal((await early(path, { ...large, 'Idempotency-Key': randomUUID() }, null)).status, 401);
    assert.equal(await records().countDocuments(), 0); assert.equal(storage.puts.length, 0);
    assert.equal((await send('album', hex(album), fileBody(await png(), 'image/png'))).status, 200);
});

test('a client that stops mid-body leaves no record and no staged object, and frees its upload slot', async () => {
    const body = fileBody(await png(64, 64, '#9a3'), 'image/png'), key = randomUUID();
    await new Promise<void>((resolve, reject) => {
        const request = httpRequest(`${base}/api/admin/v1/catalog/album/${hex(album)}/cover-uploads`, { method: 'POST', headers: { Authorization: `Bearer ${token}`,
            'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': String(body.length), 'Idempotency-Key': key } });
        request.on('response', () => reject(new Error('A partial body was answered')));
        request.on('error', () => undefined);
        request.write(body.subarray(0, body.length >> 1), () => setTimeout(() => { request.destroy(); resolve(); }, 100));
    });
    // The slot is released once the server has seen the disconnect.
    let response = await send('album', hex(album), body);
    for (let attempt = 0; response.status === 429 && attempt < 50; attempt++) { await new Promise(resolve => setTimeout(resolve, 20)); response = await send('album', hex(album), body); }
    assert.equal(response.status, 200);
    assert.equal(await records().countDocuments({ operationId: key }), 0); assert.equal(await records().countDocuments(), 1); assert.equal(storage.puts.length, 1);
});

test('a replay with the same key and bytes answers the same upload, other bytes conflict, and an unknown transfer is resumed by its retry', async () => {
    const key = randomUUID(), first = await png(5, 5, '#123'), body = fileBody(first, 'image/png');
    const id = await staged('artist', first, 'cover.png', key);
    const replay = await send('artist', hex(artist), body, key); assert.equal(replay.status, 200); assert.equal((await replay.json()).upload.id, id); assert.equal(storage.puts.length, 1);
    await expectCode(await send('artist', hex(artist), fileBody(await png(5, 5, '#321'), 'image/png'), key), 409, 'ADMIN_CATALOG_IDEMPOTENCY_CONFLICT');
    const unknownKey = randomUUID(), retried = fileBody(await png(7, 3, '#0a0'), 'image/png'); storage.failPut = true;
    await expectCode(await send('album', hex(album), retried, unknownKey), 503, 'ADMIN_CATALOG_COVER_UNKNOWN');
    const unknown = (await records().findOne({ operationId: unknownKey }))!; assert.equal(unknown.asset.state, 'unknown'); assert.equal(unknown.asset.leaseOwner, null);
    storage.failPut = false; const resumed = await send('album', hex(album), retried, unknownKey); assert.equal(resumed.status, 200); assert.equal((await resumed.json()).upload.id, hex(unknown._id));
    assert.equal(storage.puts.length, 3); assert.deepEqual(storage.puts[2].bytes, storage.puts[1].bytes); assert.equal(storage.puts[2].target.sha256, unknown.asset.sha256);
    assert.equal((await record(hex(unknown._id))).asset.state, 'ready');
});

