test('a used upload whose item is deleted is kept while its approval needs attention, and deleted once the cancelled approval\'s cleanup is confirmed', async () => {
    const id = await staged('album'), operationId = randomUUID(), path = `/catalog/album/${hex(album)}/cover-operations/${operationId}`;
    // The Album is deleted while the copy is in flight, so the new cover cannot be attached.
    storage.onCopy = async () => { await db().collection('albums').deleteOne({ _id: album }); };
    await expectCode(await approve('album', { operationId, expectedRevision: await revision('album'), uploadId: id }), 404, 'ADMIN_CATALOG_NOT_FOUND');
    storage.onCopy = undefined;
    const operation = (await operations().findOne({ operationId }))!;
    assert.deepEqual([operation.state, operation.cleanupPending, operation.stage], ['needsAttention', true, 'stored']); assert.equal((await record(id)).usedBy, hex(operation._id));
    assert.equal(await runCatalogCoverUploadCleanupOnce(proxy, undefined, later(200_000)), true); assert.equal((await record(id)).asset.state, 'ready');
    const cancelKey = randomUUID(), cancelled = await post(`${path}/cancel`, JSON.stringify({ operationId: cancelKey, expectedRevision: null }), { 'Content-Type': 'application/json' });
    assert.equal(cancelled.status, 200);
    assert.deepEqual(await cancelled.json(), { item: null, receipt: { operationId: cancelKey }, coverOperation: { state: 'cancelled', cleanupPending: false } });
    assert.equal(storage.objects.has(operation.target.key), false);
    assert.equal(await runCatalogCoverUploadCleanupOnce(proxy, undefined, later(3_600_000 + 200_001)), true);
    assert.equal((await record(id)).asset.state, 'deleted'); assert.equal(storage.objects.size, 0);
});

test('a worker tick with no operation runs one cleanup pass, and a stopped worker leaves its claim to the lease', async () => {
    const id = await staged('album'); await age(id, 25);
    assert.equal(await runAdminCatalogCoverTick(dependencies), true); assert.equal((await record(id)).asset.state, 'deleted');
    assert.equal(await runAdminCatalogCoverTick(dependencies), false);
    const warnings: unknown[] = [], warn = console.warn; console.warn = (value: unknown) => { warnings.push(value); };
    try {
        const stopped = await staged('album'); await age(stopped, 25); const controller = new AbortController();
        storage.onHead = () => { controller.abort(); throw new Error('synthetic worker stop'); };
        assert.equal(await runAdminCatalogCoverTick(dependencies, controller.signal), true); storage.onHead = undefined;
        const claimed = await record(stopped); assert.equal(claimed.asset.state, 'deleting'); assert.ok(claimed.leaseOwner);
        assert.ok(Math.abs(claimed.leaseUntil.getTime() - Date.now() - COVER_UPLOAD_LIMITS.leaseMs) < 10_000); assert.deepEqual(warnings, []);
        assert.equal(await runCatalogCoverUploadCleanupOnce(proxy, undefined, later(60_000)), false);
        assert.equal(await runCatalogCoverUploadCleanupOnce(proxy, undefined, later(COVER_UPLOAD_LIMITS.leaseMs + 10_000)), true);
        assert.equal((await record(stopped)).asset.state, 'deleted'); assert.equal(storage.objects.size, 0);
    } finally { console.warn = warn; }
});
